<?php
namespace App\Http\Controllers\Api\Admin;
use App\Http\Controllers\Controller;use Illuminate\Database\Query\Builder;use Illuminate\Http\JsonResponse;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\Validation\Rule;use Illuminate\Validation\ValidationException;
class EcosystemDependencyController extends Controller{
 private function view(Request $r):void{abort_unless($r->user()->hasPermission('ecosystem.modules.view'),403);}private function write(Request $r):void{abort_unless($r->user()->hasPermission('ecosystem.modules.configure'),403);}
 public function dashboard(Request $r):JsonResponse{$this->view($r);$q=$this->filtered($r);$total=(clone$q)->count();$count=fn($c,$v)=>(clone$q)->where($c,$v)->count();$cycles=$this->cycles();return $this->successResponse(['dashboard'=>['summary'=>['dependencies'=>$total,'required'=>$count('d.is_required',1),'optional'=>$count('d.is_required',0),'active'=>$count('d.is_active',1),'compatible'=>$count('d.compatibility_status','compatible'),'incompatible'=>$count('d.compatibility_status','incompatible'),'notEvaluated'=>$count('d.compatibility_status','not_evaluated'),'cycles'=>count($cycles),'exceptions'=>DB::table('ecosystem_dependency_exceptions')->where('status','open')->count()],'graph'=>$this->graph($q),'compatibility'=>$this->distribution($q,'d.compatibility_status'),'risks'=>$this->distribution($q,'d.risk_level'),'cycles'=>$cycles,'health'=>['score'=>null,'status'=>$total===0?'not_evaluated':($count('d.compatibility_status','incompatible')?'warning':'not_evaluated'),'reason'=>'No documented numeric dependency-health formula exists.'],'activity'=>$this->activity(),'permissions'=>['canCreate'=>$r->user()->hasPermission('ecosystem.modules.configure'),'canValidate'=>$r->user()->hasPermission('ecosystem.modules.configure'),'canDelete'=>$r->user()->hasPermission('ecosystem.modules.configure'),'canExport'=>$r->user()->hasPermission('ecosystem.modules.view')],'generatedAt'=>now()->toIso8601String()]]);}
 public function index(Request $r):JsonResponse{$this->view($r);$v=$r->validate(['search'=>['nullable','string','max:160'],'environment'=>['nullable','string','max:30'],'compatibility'=>['nullable','string','max:30'],'risk'=>['nullable','string','max:20'],'required'=>['nullable','boolean'],'sort'=>['nullable',Rule::in(['updated_at','dependency_type','compatibility_status','risk_level','source_name','target_name'])],'direction'=>['nullable',Rule::in(['asc','desc'])],'per_page'=>['nullable','integer','min:1','max:100']]);$q=$this->filtered($r);$sort=['source_name'=>'source.name','target_name'=>'target.name'][$v['sort']??'']??'d.'.($v['sort']??'updated_at');return $this->successResponse(['dependencies'=>$q->select($this->columns())->orderBy($sort,$v['direction']??'desc')->paginate($v['per_page']??20)]);}
 public function references(Request $r):JsonResponse{$this->view($r);return $this->successResponse(['references'=>['modules'=>DB::table('ecosystem_modules')->whereNull('deleted_at')->orderBy('name')->get(['id','module_key','name','current_version','status','is_enabled']),'environments'=>['development','test','staging','production','sandbox']]]);}
 public function store(Request $r):JsonResponse{$this->write($r);$d=$this->validated($r);abort_if($d['ecosystem_module_id']===$d['dependency_module_id'],422,'A module cannot depend on itself.');abort_if(DB::table('ecosystem_module_dependencies')->where('ecosystem_module_id',$d['ecosystem_module_id'])->where('dependency_module_id',$d['dependency_module_id'])->exists(),409,'Dependency already exists.');$id=DB::transaction(function()use($r,$d){$id=DB::table('ecosystem_module_dependencies')->insertGetId([...$d,'status'=>'not_validated','compatibility_status'=>'not_evaluated','risk_level'=>'unknown','is_active'=>true,'created_by'=>$r->user()->id,'updated_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);if($this->hasPath($d['dependency_module_id'],$d['ecosystem_module_id'])){DB::table('ecosystem_module_dependencies')->where('id',$id)->delete();throw ValidationException::withMessages(['dependency_module_id'=>'This relationship creates a circular dependency.']);}$this->audit($id,$r,'created',null,$d);return$id;});return $this->successResponse(['dependency'=>DB::table('ecosystem_module_dependencies')->find($id)],'Dependency created.',201);}
 public function validateDependency(Request $r,int $id):JsonResponse{$this->write($r);$dep=DB::table('ecosystem_module_dependencies as d')->join('ecosystem_modules as target','target.id','=','d.dependency_module_id')->where('d.id',$id)->first(['d.*','target.current_version','target.is_enabled as target_is_enabled','target.status as target_status']);abort_unless($dep,404);$reasons=[];$compatible=true;if($dep->is_required&&!$dep->target_is_enabled){$compatible=false;$reasons[]='Required target module is disabled.';}if($dep->required_version&&$dep->current_version){try{if(!$this->satisfies(ltrim($dep->current_version,'vV'),$dep->required_version)){$compatible=false;$reasons[]='Target module version does not satisfy the required semantic-version constraint.';}}catch(\InvalidArgumentException){$compatible=false;$reasons[]='Required version constraint is invalid.';}}elseif($dep->required_version){$compatible=false;$reasons[]='Target module version is unavailable.';}$status=$compatible?'compatible':'incompatible';DB::transaction(function()use($r,$id,$dep,$status,$reasons){DB::table('ecosystem_module_dependencies')->where('id',$id)->update(['status'=>$status==='compatible'?'validated':'failed','compatibility_status'=>$status,'risk_level'=>$status==='compatible'?'low':($dep->is_required?'high':'medium'),'validation_reasons'=>json_encode($reasons),'last_validated_at'=>now(),'updated_by'=>$r->user()->id,'updated_at'=>now()]);$this->audit($id,$r,'validated',(array)$dep,['compatibility_status'=>$status,'reasons'=>$reasons]);});return $this->successResponse(['validation'=>['compatible'=>$compatible,'status'=>$status,'reasons'=>$reasons]]);}
 public function destroy(Request $r,int $id):JsonResponse{$this->write($r);$before=DB::table('ecosystem_module_dependencies')->find($id);abort_unless($before,404);DB::transaction(function()use($r,$id,$before){$this->audit($id,$r,'removed',(array)$before,null);DB::table('ecosystem_module_dependencies')->where('id',$id)->delete();});return $this->successResponse(message:'Dependency removed.');}
 public function export(Request $r):JsonResponse{$this->view($r);return response()->json(['source'=>'database','generatedAt'=>now()->toIso8601String(),'nodes'=>$this->graph($this->filtered($r))['nodes'],'dependencies'=>$this->filtered($r)->select($this->columns())->get()]);}
 private function filtered(Request $r):Builder{$q=DB::table('ecosystem_module_dependencies as d')->join('ecosystem_modules as source','source.id','=','d.ecosystem_module_id')->join('ecosystem_modules as target','target.id','=','d.dependency_module_id');if($s=trim((string)$r->search))$q->where(fn($x)=>$x->where('source.name','like',"%$s%")->orWhere('target.name','like',"%$s%"));foreach(['environment'=>'d.environment','compatibility'=>'d.compatibility_status','risk'=>'d.risk_level']as$k=>$c)if($r->filled($k))$q->where($c,$r->$k);if($r->filled('required'))$q->where('d.is_required',$r->boolean('required'));return$q;}
 private function columns():array{return['d.id','source.id as source_id','source.module_key as source_key','source.name as source_name','source.current_version as source_version','target.id as target_id','target.module_key as target_key','target.name as target_name','target.current_version as target_version','d.dependency_type','d.environment','d.required_version','d.is_required','d.is_active','d.status','d.compatibility_status','d.risk_level','d.validation_reasons','d.last_validated_at','d.updated_at'];}
 private function graph(Builder $q):array{$rows=(clone$q)->select($this->columns())->get();$nodes=[];foreach($rows as$x){$nodes[$x->source_id]=['id'=>$x->source_id,'key'=>$x->source_key,'name'=>$x->source_name,'type'=>'module'];$nodes[$x->target_id]=['id'=>$x->target_id,'key'=>$x->target_key,'name'=>$x->target_name,'type'=>'module'];}return['nodes'=>array_values($nodes),'edges'=>$rows->map(fn($x)=>['id'=>$x->id,'source'=>$x->source_id,'target'=>$x->target_id,'required'=>(bool)$x->is_required,'type'=>$x->dependency_type,'compatibility'=>$x->compatibility_status,'risk'=>$x->risk_level])->values()];}
 private function cycles():array{$adj=[];foreach(DB::table('ecosystem_module_dependencies')->where('is_active',1)->get(['ecosystem_module_id','dependency_module_id'])as$d)$adj[$d->ecosystem_module_id][]=$d->dependency_module_id;$cycles=[];$walk=function($node,$path)use(&$walk,&$cycles,$adj){$pos=array_search($node,$path,true);if($pos!==false){$cycle=array_slice($path,$pos);$cycle[]=$node;$key=implode('>',$cycle);$cycles[$key]=$cycle;return;}if(count($path)>100)return;foreach($adj[$node]??[]as$n)$walk($n,[...$path,$node]);};foreach(array_keys($adj)as$n)$walk($n,[]);return array_values($cycles);}
 private function hasPath(int $from,int $to):bool{$seen=[];$stack=[$from];while($stack){$n=array_pop($stack);if($n===$to)return true;if(isset($seen[$n]))continue;$seen[$n]=true;foreach(DB::table('ecosystem_module_dependencies')->where('ecosystem_module_id',$n)->where('is_active',1)->pluck('dependency_module_id')as$x)$stack[]=$x;}return false;}
 private function satisfies(string $version,string $constraint):bool{$version=preg_replace('/[^0-9.].*$/','',$version)??'';$constraint=trim($constraint);if(!preg_match('/^\d+(?:\.\d+){0,2}$/',$version)||$constraint==='')throw new \InvalidArgumentException();if(str_starts_with($constraint,'^')||str_starts_with($constraint,'~')){$kind=$constraint[0];$base=substr($constraint,1);if(!preg_match('/^\d+(?:\.\d+){0,2}$/',$base))throw new \InvalidArgumentException();$parts=array_map('intval',explode('.',$base));$base=implode('.',array_pad($parts,3,0));if($kind==='^'){$upper=($parts[0]??0)>0?(($parts[0]+1).'.0.0'):'0.'.(($parts[1]??0)+1).'.0';}else{$upper=($parts[0]??0).'.'.(($parts[1]??0)+1).'.0';}return version_compare($version,$base,'>=')&&version_compare($version,$upper,'<');}if(preg_match('/^(>=|<=|>|<|=)?\s*(\d+(?:\.\d+){0,2})$/',$constraint,$m))return version_compare($version,$m[2],$m[1]?:'==');if(preg_match('/^(\d+)(?:\.(\d+))?\.(?:x|\*)$/i',$constraint,$m)){$prefix=$m[1].(isset($m[2])?'.'.$m[2]:'');return str_starts_with($version,$prefix.'.');}throw new \InvalidArgumentException();}
 private function validated(Request $r):array{return$r->validate(['ecosystem_module_id'=>['required','integer','exists:ecosystem_modules,id'],'dependency_module_id'=>['required','integer','exists:ecosystem_modules,id'],'dependency_type'=>['required',Rule::in(['runtime','data','integration','shared_service','build'])],'environment'=>['required',Rule::in(['development','test','staging','production','sandbox'])],'required_version'=>['nullable','string','max:80'],'is_required'=>['required','boolean']]);}
 private function distribution(Builder$q,string$c){return(clone$q)->select($c.' as key',DB::raw('COUNT(*) as count'))->groupBy($c)->get();}private function activity(){return DB::table('ecosystem_dependency_audits as a')->leftJoin('users as u','u.id','=','a.actor_id')->orderByDesc('a.created_at')->limit(12)->get(['a.id','a.dependency_id','a.action','u.name as actor','a.created_at']);}private function audit(?int$id,Request$r,string$a,?array$b,?array$f):void{DB::table('ecosystem_dependency_audits')->insert(['dependency_id'=>$id,'action'=>$a,'actor_id'=>$r->user()->id,'before'=>$b?json_encode($b):null,'after'=>$f?json_encode($f):null,'created_at'=>now()]);}
}
